      "translation": "obdelovati • pozidati",
      "explanation": [
        "Glavna misel: bebauen je glagol z dvema pomenoma: pozidati zemljišče s stavbami in obdelovati zemljo, polje v kmetijstvu. Je neločljiv in se veže z akuzativom.",
        "Oblike: bebaut, bebaute, hat bebaut. Pogost deležnik bebaut se uporablja kot pridevnik: dicht bebaut (gosto pozidan), unbebaut (nepozidan). Za stavbe se reče mit Häusern bebauen.",
        "Za polja se uporablja tudi anbauen (gojiti kulturo): Weizen anbauen; bebauen je širše in pomeni obdelovanje zemlje nasploh."
      ],
      "examples": [
        {
          "de": "Das Grundstück wird mit Wohnhäusern bebaut.",
          "lv": "Zemljišče pozidavajo s stanovanjskimi hišami."
        },
        {
          "de": "Die Bauern bebauen das Feld mit Weizen.",
          "lv": "Kmetje obdelujejo polje in na njem sejejo pšenico."
        },
        {
          "de": "Das Gelände darf nicht bebaut werden.",
          "lv": "Tega območja ni dovoljeno pozidati."
        },
        {
          "de": "Der Hang ist dicht bebaut.",
          "lv": "Pobočje je gosto pozidano."
        }
      ],
      "comparison": [
        {
          "word": "bauen",
          "meaning": "graditi",
          "example": "Sie bauen ein Haus. – Gradijo hišo."
        },
        {
          "word": "anbauen",
          "meaning": "gojiti, prizidati",
          "example": "Hier baut man Wein an. – Tukaj gojijo vinsko trto."
        },
        {
          "word": "bearbeiten",
          "meaning": "obdelovati",
          "example": "Er bearbeitet den Boden. – Obdeluje zemljo."
        }
      ],
      "tip": [
        "V pomenu stavb se uporablja mit: mit Häusern bebauen; pogosto ga vidiš tudi v trpniku: bebaut werden.",
        "Nasprotje je unbebaut — nepozidan."
      ],
      "important": [
        "Bebauen ni isto kot bauen: bauen pomeni nekaj graditi, bebauen pa pokriti zemljišče z zgradbami.",
        "V kmetijstvu se za gojenje rastlin pogosteje uporablja anbauen."
      ],
